import { delete_broadcast_channel } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    deleteBroadcast: Boolean,
    broadcast_info: Object
  },
  data() {
    return {
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_event() {
      this.loading = true;
      try {
        const userData = this.$store.getters.GetUserObj;
        if (!userData || !userData.user) {
          throw new Error("User data not available");
        }
        let result = await API.graphql(graphqlOperation(delete_broadcast_channel, {
          input: {
            team_id: this.broadcast_info.team_id,
            user_email_id: userData.user.user_email_id
          }
        }));
        var response = JSON.parse(result.data.delete_broadcast_channel);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.close_dialog();
        } else {
          this.$emit("errorMsg", response.Message || "Failed to delete broadcast channel");
        }
      } catch (error) {
        console.error("Error deleting broadcast channel:", error);
        const errorMessage = error.errors && error.errors[0] ? error.errors[0].message : "Failed to delete broadcast channel. Please try again.";
        this.$emit("errorMsg", errorMessage);
      } finally {
        this.loading = false;
      }
    }
  }
};
